        Files.deleteIfExists(Paths.get("todo.csv"));
        String perintah = "tambah Belajar Java\ntambah Beli kopi\ntambah Latihan OOP\nselesai 1\nhapus 2\ncari java\nstatistik\nkeluar\n";
        TodoService service = new TodoService(new TodoRepositoryFile("todo.csv"));
        new TodoView(service).jalankan(new Scanner(perintah));
    }
}

class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this(id, judul, false);
    }

    Todo(int id, String judul, boolean selesai) {
        this.id = id;
        this.judul = judul;
        this.selesai = selesai;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

interface TodoRepository {
    Todo simpan(String judul);

    List<Todo> semua();

    Todo cari(int id);

    boolean hapus(int id);

    void perbarui(Todo todo);
}

class TodoRepositoryFile implements TodoRepository {
    private final Path file;

    TodoRepositoryFile(String nama) {
        this.file = Paths.get(nama);
    }

    private List<Todo> muat() {
        List<Todo> hasil = new ArrayList<>();
        try {
            if (!Files.exists(file)) {
                return hasil;
            }
            for (String b : Files.readAllLines(file)) {
                String[] d = b.split(";", 3);
                hasil.add(new Todo(Integer.parseInt(d[0]), d[2], d[1].equals("1")));
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return hasil;
    }

    private void tulis(List<Todo> data) {
        List<String> baris = new ArrayList<>();
        for (Todo t : data) {
            baris.add(t.getId() + ";" + (t.isSelesai() ? "1" : "0") + ";" + t.getJudul());
        }
        try {
            Files.write(file, baris);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public Todo simpan(String judul) {
        List<Todo> data = muat();
        int id = 1;
        for (Todo t : data) {
            id = Math.max(id, t.getId() + 1);
        }
        Todo baru = new Todo(id, judul);
        data.add(baru);
        tulis(data);
        return baru;
    }

    public List<Todo> semua() {
        return muat();
    }

    public Todo cari(int id) {
        for (Todo t : muat()) {
            if (t.getId() == id) {
                return t;
            }
        }
        return null;
    }

    public boolean hapus(int id) {
        List<Todo> data = muat();
        boolean ada = data.removeIf(t -> t.getId() == id);
        tulis(data);
        return ada;
    }

    public void perbarui(Todo todo) {
        List<Todo> data = muat();
        for (int i = 0; i < data.size(); i++) {
            if (data.get(i).getId() == todo.getId()) {
                data.set(i, todo);
            }
        }
        tulis(data);
    }
}

class TodoTidakDitemukanException extends RuntimeException {
    TodoTidakDitemukanException(int id) {
        super("Todo nomor " + id + " tidak ditemukan");
    }
}

class TodoService {
    private final TodoRepository repo;

    TodoService(TodoRepository repo) {
        this.repo = repo;
    }

    Todo tambah(String judul) {
        if (judul == null || judul.trim().isEmpty()) {
            throw new IllegalArgumentException("Judul tidak boleh kosong");
        }
        if (judul.trim().length() > 50) {
            throw new IllegalArgumentException("Judul maksimal 50 huruf");
        }
        return repo.simpan(judul.trim());
    }

    void selesaikan(int id) {
        Todo t = repo.cari(id);
        if (t == null) {
            throw new TodoTidakDitemukanException(id);
        }
        t.selesaikan();
        repo.perbarui(t);
    }

    void hapus(int id) {
        if (!repo.hapus(id)) {
            throw new TodoTidakDitemukanException(id);
        }
    }

    List<Todo> semua() {
        return repo.semua();
    }

    List<Todo> cari(String kata) {
        String k = kata.toLowerCase();
        return repo.semua().stream()
                .filter(t -> t.getJudul().toLowerCase().contains(k))
                .collect(Collectors.toList());
    }

    long jumlahSelesai() {
        return repo.semua().stream().filter(Todo::isSelesai).count();
    }
}

class TodoView {
    private final TodoService service;

    TodoView(TodoService service) {
        this.service = service;
    }

    void jalankan(Scanner in) {
        while (in.hasNextLine()) {
            String baris = in.nextLine().trim();
            if (baris.equals("keluar")) {
                System.out.println("Sampai jumpa!");
                return;
            }
            try {
                proses(baris);
            } catch (IllegalArgumentException | TodoTidakDitemukanException e) {
                System.out.println("Gagal: " + e.getMessage());
            }
        }
    }

    void proses(String baris) {
        String[] p = baris.split(" ", 2);
        String isi = p.length > 1 ? p[1] : "";
        switch (p[0]) {
            case "tambah":
                Todo t = service.tambah(isi);
                System.out.println("Ditambah: " + t);
                break;
            case "selesai":
                service.selesaikan(angka(isi));
                System.out.println("Selesai nomor " + isi);
                break;
            case "hapus":
                service.hapus(angka(isi));
                System.out.println("Dihapus nomor " + isi);
                break;
            case "lihat":
                lihat();
                break;
            case "cari":
                for (Todo x : service.cari(isi)) {
                    System.out.println(x);
                }
                break;
            case "statistik":
                System.out.println(service.jumlahSelesai() + " dari " + service.semua().size() + " selesai");
                break;
            default:
                System.out.println("Perintah tidak dikenal: " + p[0]);
        }
    }

    void lihat() {
        List<Todo> semua = service.semua();
        if (semua.isEmpty()) {
            System.out.println("Belum ada todo");
        }
        for (Todo t : semua) {
            System.out.println(t);
        }
    }

    private int angka(String s) {
        try {
            return Integer.parseInt(s.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Nomor harus angka: " + s);
        }
    }
}

