    List<Todo> cari(String kata) {
        String k = kata.toLowerCase();
        return repo.semua().stream()
                .filter(t -> t.getJudul().toLowerCase().contains(k))
                .collect(Collectors.toList());
    }

    int bersihkan() {
        int n = 0;
        for (Todo t : repo.semua()) {
            if (t.isSelesai()) {
                repo.hapus(t.getId());
                n++;
            }
        }
        return n;
    }

    long jumlahSelesai() {
        return repo.semua().stream().filter(Todo::isSelesai).count();
    }
}

class TodoView {
    private final TodoService service;

    TodoView(TodoService service) {
        this.service = service;
    }

    void jalankan(Scanner in) {
        while (in.hasNextLine()) {
            String baris = in.nextLine().trim();
            if (baris.equals("keluar")) {
                System.out.println("Sampai jumpa!");
                return;
            }
            try {
                proses(baris);
            } catch (IllegalArgumentException | TodoTidakDitemukanException e) {
                System.out.println("Gagal: " + e.getMessage());
            }
        }
    }

    void proses(String baris) {
        String[] p = baris.split(" ", 2);
        String isi = p.length > 1 ? p[1] : "";
        switch (p[0]) {
            case "tambah":
                Todo t = service.tambah(isi);
                System.out.println("Ditambah: " + t);
                break;
            case "selesai":
                service.selesaikan(angka(isi));
                System.out.println("Selesai nomor " + isi);
                break;
            case "hapus":
                service.hapus(angka(isi));
                System.out.println("Dihapus nomor " + isi);
                break;
            case "lihat":
                lihat();
                break;
            case "cari":
                for (Todo x : service.cari(isi)) {
                    System.out.println(x);
                }
                break;
            case "bersihkan":
                System.out.println("Dibersihkan: " + service.bersihkan() + " todo");
                break;
            case "statistik":
                System.out.println(service.jumlahSelesai() + " dari " + service.semua().size() + " selesai");
                break;
            default:
                System.out.println("Perintah tidak dikenal: " + p[0]);
        }
    }

    void lihat() {
        List<Todo> semua = service.semua();
        if (semua.isEmpty()) {
            System.out.println("Belum ada todo");
        }
        for (Todo t : semua) {
            System.out.println(t);
        }
    }

    private int angka(String s) {
        try {
            return Integer.parseInt(s.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Nomor harus angka: " + s);
        }
    }
}
